<h2 class="mb-3">Tài khoản khách hàng</h2><div class="d-flex justify-content-end mb-3"><a class="btn btn-primary" href="<?= htmlspecialchars(BASE_URL . '/accounts/create') ?>">Tạo tài khoản</a></div><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>#</th><th>Username</th><th>Tên hiển thị</th><th>Số dư</th><th>Combo</th><th>Trạng thái</th></tr></thead><tbody><?php foreach ($accounts as $account): ?><tr><td><?= (int) $account['id'] ?></td><td><?= htmlspecialchars((string) $account['username']) ?></td><td><?= htmlspecialchars((string) $account['display_name']) ?></td><td><?= number_format((float) $account['balance'], 0, ',', '.') ?> đ</td><td><?= (int) $account['active_combos'] ?></td><td><?= htmlspecialchars((string) $account['status']) ?></td></tr><?php endforeach; ?><?php if ($accounts === []): ?><tr><td colspan="6" class="text-center text-muted">Chưa có tài khoản.</td></tr><?php endif; ?></tbody></table></div>
